task.starter_code:
// The markup is already on the page: #like-btn, #like-count, #theme-toggle,
// #faq with .faq__item blocks (.faq__question + .faq__answer), #comment, #comment-counter.

// 1. Likes: let likes = 0; click → +1

// 2. Theme: the class theme-dark on body, aria-pressed on the button

// 3. Questions: ONE handler on #faq, event.target.closest(".faq__question")

// 4. Escape closes all answers

// 5. Character counter: the input event

task.solution:
// 1. Likes
const likeButton = document.querySelector("#like-btn");
const likeCount = document.querySelector("#like-count");
let likes = 0;

likeButton.addEventListener("click", () => {
    likes++;
    likeCount.textContent = String(likes);
});

// 2. Theme
const themeButton = document.querySelector("#theme-toggle");

themeButton.addEventListener("click", () => {
    const isDark = document.body.classList.toggle("theme-dark");
    themeButton.setAttribute("aria-pressed", String(isDark));
});

// 3. Questions: one handler on #faq
const faq = document.querySelector("#faq");

faq.addEventListener("click", (event) => {
    const question = event.target.closest(".faq__question");
    if (!question) {
        return;
    }

    const answer = question.closest(".faq__item").querySelector(".faq__answer");
    const willOpen = answer.hidden;

    answer.hidden = !willOpen;
    question.setAttribute("aria-expanded", String(willOpen));
});

// 4. Escape closes all answers
document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") {
        return;
    }
    for (const item of faq.querySelectorAll(".faq__item")) {
        item.querySelector(".faq__answer").hidden = true;
        item.querySelector(".faq__question").setAttribute("aria-expanded", "false");
    }
});

// 5. Character counter
const comment = document.querySelector("#comment");
const commentCounter = document.querySelector("#comment-counter");

comment.addEventListener("input", () => {
    commentCounter.textContent = `${comment.value.length} / 100`;
});

